import React, { useEffect, useState } from 'react';
import MovieCard from '../components/MovieCard';

// 임시 데이터 (이 부분은 이전과 동일합니다)
const MOCK_MOVIES = [
    // ... 이전과 동일한 영화 데이터 ...
    {
      id: 1,
      title: '영화 1',
      poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
      description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
    },
    {
      id: 2,
      title: '영화 2',
      poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
      details: {
        '영화 제목': '영화 2',
        '개봉일': '2025.01.01',
        '감독': '홍길동',
        '배우': '김배우, 이배우',
        '장르': '드라마',
        '관람 등급': '15세 이상 관람가',
      },
    },
    {
      id: 3,
      title: '영화 3',
      poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
      description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
    },
    {
      id: 4,
      title: '영화 4',
      poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
      description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
    },
    {
      id: 5,
      title: '영화 5',
      poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
      description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
    },
    {
      id: 6,
      title: '영화 6',
      poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
      description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
    },
];

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // ... 이전과 동일한 useEffect 로직 ...
    const fetchMovies = async () => {
      try {
        setLoading(true);
        setTimeout(() => {
          setMovies(MOCK_MOVIES);
          setLoading(false);
        }, 500);
      } catch (error) {
        console.error("영화 정보를 가져오는 데 실패했습니다.", error);
        setLoading(false);
      }
    };
    fetchMovies();
  }, []);


  if (loading) return <div>로딩 중...</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>박스오피스</h1>
      <div style={styles.movieGrid}>
        {movies.map(movie => (
          <MovieCard key={movie.id} movie={movie} />
        ))}
      </div>
    </div>
  );
}

// 스타일 객체 수정
const styles = {
  container: {
    width: '100%',
    maxWidth: '1200px',
    margin: '0 auto',
    padding: '2rem',
    // backgroundColor: '#f0f2f5', // 이 라인을 삭제하거나 주석 처리하여 배경색 제거
    boxSizing: 'border-box',
  },
  title: {
    fontSize: '2.5rem',
    textAlign: 'center',
    marginBottom: '3rem',
    fontWeight: 'bold',
  },
  movieGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(3, 1fr)',
    // 'gap'을 'row-gap'과 'column-gap'으로 분리하여 상하 간격을 더 넓게 설정
    columnGap: '2rem', // 좌우 간격
    rowGap: '3rem', // 상하 간격 (기존 2rem에서 3rem으로 증가)
  },
};

export default HomePage;
